contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We'll take an amount to forward to c.go. We must ensure this contract has enough balance.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");
        // record balances before the call
        uint256 beforeTestBalance = address(this).balance;
        uint256 beforeCbalance = address(c).balance;
        // call c.go forwarding 'amount' wei and catch whether it reverts
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // read balances after
        uint256 afterTestBalance = address(this).balance;
        uint256 afterCbalance = address(c).balance;
        // General rule: If the call succeeded (did not revert) then c's balance is zero
        // and this test contract's balance did not increase (it may have decreased by gas or by sending amount).
        // We express: if not reverted then afterCbalance == 0 and afterTestBalance <= beforeTestBalance
        assert(reverted || (afterCbalance == 0 && afterTestBalance <= beforeTestBalance));
    }
    receive() external payable {}
}

